def is_time_between(check_hhmm, start_hhmm, end_hhmm):
    def to_minutes(t):
        h, m = t.split(':')
        return int(h) * 60 + int(m)
    c = to_minutes(check_hhmm)
    s = to_minutes(start_hhmm)
    e = to_minutes(end_hhmm)
    if e <= s:
        e += 1440
        if c < s:
            c += 1440
    return s <= c < e

